const express = require('express');
const app = express();

// Lightweight DB connectivity check used by the readiness probe.
// `db` is expected to expose a `query` method (e.g. a pg Pool/Client).
// It can be injected for testing; falls back to a lazily-created pool.
let db = null;
function getDb() {
  if (db) return db;
  try {
    const { Pool } = require('pg');
    db = new Pool({ connectionString: process.env.DATABASE_URL });
  } catch (err) {
    // pg not installed / not configured; healthz will report failure.
    db = null;
  }
  return db;
}

async function checkDb() {
  const client = getDb();
  if (!client) return false;
  try {
    await client.query('SELECT 1');
    return true;
  } catch (err) {
    return false;
  }
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Readiness probe for k8s: 200 when Postgres is reachable, 503 otherwise.
app.get('/healthz', async (req, res) => {
  const ok = await checkDb();
  if (ok) {
    res.status(200).json({ db: 'ok' });
  } else {
    res.status(503).json({ db: 'error' });
  }
});

module.exports = app;
// Exposed for testing: allows injecting a mock DB client.
module.exports.setDb = (client) => { db = client; };

