// Lazily create a Postgres pool from the environment-provided connection
// string. We never log or expose the connection details.
let pool = null;
function getPool() {
  if (pool) return pool;
  if (!process.env.DATABASE_URL) return null;
  try {
    const { Pool } = require('pg');
    pool = new Pool({ connectionString: process.env.DATABASE_URL });
  } catch (err) {
    // pg not installed / unavailable
    pool = null;
  }
  return pool;
}

